INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('reading', '{"text": "Coffee is one of the most traded products in the world. It is grown mainly in warm countries near the equator, such as Brazil, Colombia, and Vietnam. Farmers pick the coffee cherries by hand or machine, then dry and roast the beans before they are sold. Millions of people drink coffee every morning to help them feel more awake and alert."}'::jsonb, '{"exact": "Coffee is one of the most traded products in the world. It is grown mainly in warm countries near the equator, such as Brazil, Colombia, and Vietnam. Farmers pick the coffee cherries by hand or machine, then dry and roast the beans before they are sold. Millions of people drink coffee every morning to help them feel more awake and alert."}'::jsonb, 65, 0.38, 'B1', 'approved', 'exam', 'general', 'b2000000-0000-4000-8000-000000000011', 1),
('reading', '{"text": "Public libraries offer much more than just books today. Many libraries now provide free internet access, computer classes, and meeting rooms for the community. Some even lend out tools, musical instruments, or seeds for gardening. Because of these services, libraries remain an important resource for people of all ages, especially those with limited access to technology at home."}'::jsonb, '{"exact": "Public libraries offer much more than just books today. Many libraries now provide free internet access, computer classes, and meeting rooms for the community. Some even lend out tools, musical instruments, or seeds for gardening. Because of these services, libraries remain an important resource for people of all ages, especially those with limited access to technology at home."}'::jsonb, 60, 0.42, 'B1', 'approved', 'exam', 'community', 'b2000000-0000-4000-8000-000000000011', 2);
