INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('typing', '{"text": "Learning a new language can open many doors in life. It allows people to communicate with others from different cultures and understand their traditions more deeply. Many language learners find that watching movies, listening to music, and reading simple books in the new language helps them improve faster than studying grammar alone. Regular practice is more effective than occasional long study sessions. Making mistakes is a normal and necessary part of the process, not something to feel embarrassed about. With enough patience and consistency, almost anyone can become confident in a second language over time."}'::jsonb, '{"exact": "Learning a new language can open many doors in life. It allows people to communicate with others from different cultures and understand their traditions more deeply. Many language learners find that watching movies, listening to music, and reading simple books in the new language helps them improve faster than studying grammar alone. Regular practice is more effective than occasional long study sessions. Making mistakes is a normal and necessary part of the process, not something to feel embarrassed about. With enough patience and consistency, almost anyone can become confident in a second language over time."}'::jsonb, 94, 0.48, 'B1', 'approved', 'exam', 'education', 'b2000000-0000-4000-8000-000000000015', 1);
