INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "Anna planned a weekend trip to the mountains with her close friends. On the way there, their car suddenly had a flat tire. A passing driver kindly stopped and helped them change it quickly. They arrived a little later than planned but still enjoyed a wonderful weekend of hiking."}'::jsonb, '{"key_points": ["Anna planned a trip with friends", "their car had a flat tire", "a passing driver helped them", "they still enjoyed the weekend"]}'::jsonb, 48, 0.50, 'B1', 'approved', 'exam', 'travel', 'b2000000-0000-4000-8000-000000000018', 1),
('passage_reconstruction', '{"passage": "Marco booked a hotel room online for his business trip. When he arrived, the hotel had no record of his reservation. After some discussion, the staff found him a similar room at no extra cost. Marco was relieved the trip was not ruined."}'::jsonb, '{"key_points": ["Marco booked a hotel online", "the hotel had no record of it", "staff found him a similar room at no extra cost", "he was relieved"]}'::jsonb, 43, 0.53, 'B2', 'approved', 'exam', 'travel', 'b2000000-0000-4000-8000-000000000018', 2),
('passage_reconstruction', '{"passage": "A tourist left her camera on a train by mistake. She reported it immediately at the next station. Three days later, the railway company contacted her, saying the camera had been found. She was delighted to get it back before the end of her trip."}'::jsonb, '{"key_points": ["a tourist left her camera on a train", "she reported it right away", "the railway found the camera days later", "she got it back before her trip ended"]}'::jsonb, 45, 0.55, 'B2', 'approved', 'exam', 'travel', 'b2000000-0000-4000-8000-000000000018', 3);
INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('summary_and_opinion', '{"passage": "Online shopping has become extremely popular over the past decade. More people now buy clothes, electronics, and groceries through websites instead of visiting physical stores. This shift has changed the way many businesses operate and has created new habits among shoppers. Some people strongly prefer online shopping, while others still enjoy the experience of shopping in person.\n\nOne major advantage of online shopping is convenience. Customers can browse thousands of products from home at any time of day, without worrying about store hours or travel. Prices are often easier to compare online, since many websites display similar products side by side. In addition, online shopping saves time for busy people who cannot easily visit multiple stores in one day.\n\nHowever, shopping in physical stores also has clear benefits. Customers can see, touch, and try on items before buying them, which reduces the chance of disappointment when the product arrives. Shopping in stores also allows people to get immediate help from staff and avoid long delivery waits. For some, visiting a store is also a social activity, offering a chance to get out of the house and interact with others.\n\nBoth online and in-store shopping offer real advantages depending on a person''s needs. Someone who values convenience may prefer shopping online, while someone who wants a hands-on experience may still choose to visit a physical store. The right option often depends on the product and the shopper."}'::jsonb, '{"key_points": ["online shopping has become very popular", "it offers convenience and easier price comparison", "physical stores let customers try items and get immediate help", "the best choice depends on the product and shopper"]}'::jsonb, 275, 0.60, 'B2', 'approved', 'exam', 'shopping', 'b2000000-0000-4000-8000-000000000019', 1);
